import{_ as n,l as i,o as e,c as s,v as t,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"意向锁与粒度","description":"","frontmatter":{"title":"意向锁与粒度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/intention-locks.md","filePath":"cs/intention-locks.md","lastUpdated":1789023840000}'),h={name:"cs/intention-locks.md"};function _(m,a,u,A,f,I){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="意向锁与粒度" tabindex="-1">意向锁与粒度 <a class="header-anchor" href="#意向锁与粒度" aria-label="Permalink to &quot;意向锁与粒度&quot;">​</a></h1><div class="epigraph"><p>要锁一行，先在表上挂意向：别人想锁整表时能看见冲突，而不必枚举所有行锁。</p><footer>—— 据 Gray, Lorie, Putzolu and Traiger 多粒度锁，1975；Gray and Reuter；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/ssi">上一课</a>在行版本上追踪冲突。本课回到悲观锁的<strong>粒度</strong>：行、页、表。主干 2PL 常默实行锁。缺口是多粒度：若只行锁，全表扫描的互斥要百万把锁；若只表锁，并发为零。意向锁（IS/IX）在祖先上做标记。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>层次：数据库–表–页–行。事务要 X 锁行：先 IX 表、IX 页，再 X 行。另一事务要 X 表：与 IX 冲突，等待，不必看每一行。缺口是<strong>相容矩阵</strong>：IS 与 IX 相容，X 与一切意向在同对象上冲突等。锁升级：行锁太多则升表锁，减少内存，增加冲突。</p><p>与 latch：latch 仍短、在页结构上；意向锁是事务锁，可持有到提交（严格 2PL）。</p><p><span class="marginnote">Gray et al. IBM 多粒度。SQL Server、DB2、InnoDB 都有表/行意向。Postgres 行锁+表级 ACCESS SHARE 等是另一套名字，机制同族。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加锁自上而下，释放自下而上（或提交一次性），避免死锁协议破环。查询计划决定粒度：全表更新应直接表锁，不要先锁每一行再升级。优化器与锁：顺序扫描仍可能行锁，HOT 更新同页。</p><p>覆盖：意向不替代行上的 X；它是祖先上的警告灯。</p>',10)),(e(),l(c,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAB%5B%22%E8%A1%A8%20IX%22%5D%20--%3E%20PG%5B%22%E9%A1%B5%20IX%22%5D%0A%20%20PG%20--%3E%20ROW%5B%22%E8%A1%8C%20X%22%5D%0A%20%20TAB2%5B%22%E8%A1%A8%20X%22%5D%20--%3E%20WAIT%5B%22%E4%B8%8E%20IX%20%E5%86%B2%E7%AA%81%E7%AD%89%E5%BE%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>死锁：两事务对表与行反序仍可环，wait-for 下一课。SSI 的 SIREAD 也是一种范围意向。分区表：锁可停在分区级。</p><p>内存：锁表项数是容量。升级阈值是调参。计划回归：突然表锁把并发打穿，像优化器选了全表更新路径。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 next-key。也不把文件锁当意向。分布式锁粒度更粗，后课。</p><p>后课默认：行锁路径必先意向祖先。间隙锁与谓词锁：防幻象的范围，不只点行。</p><p>没有意向，表级互斥只能靠「锁所有行」或「总是表锁」两端。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多粒度用 IS/IX 标记祖先，使表锁与行锁可检测冲突。</li><li>加锁自上而下；升级是容量阀门。</li><li>间隙锁与谓词锁下一课。</li><li>出处：Gray et al. 1975；Gray and Reuter；Ramakrishnan and Gehrke。</li></ul>',9))])}const T=n(h,[["render",_]]);export{E as __pageData,T as default};
